def base(landscape=False):
 d=Document();s=d.sections[0]
 s.page_width=Cm(29.7 if landscape else 21);s.page_height=Cm(21 if landscape else 29.7)
 s.top_margin=s.bottom_margin=Cm(1.6);s.left_margin=Cm(2);s.right_margin=Cm(1.8)
 n=d.styles['Normal'];n.font.name='Arial';n.font.size=Pt(10);n.font.color.rgb=RGBColor.from_string('303539');n.paragraph_format.space_after=Pt(6);n.paragraph_format.line_spacing=1.1
 for k,size in [('Title',15),('Heading 1',11),('Heading 2',10)]:
  x=d.styles[k];x.font.name='Arial';x.font.size=Pt(size);x.font.bold=True;x.font.color.rgb=RGBColor.from_string('303539');x.paragraph_format.space_before=Pt(9);x.paragraph_format.space_after=Pt(4)
  for b in x._element.get_or_add_pPr().findall(qn('w:pBdr')):x._element.get_or_add_pPr().remove(b)
 return d
def p(d,t,style=None):return d.add_paragraph(t,style)
def h(d,t):return p(d,t,'Heading 1')
def title(d,t):return p(d,t,'Title')
def table(d,rows,widths=None):
 t=d.add_table(rows=0,cols=len(rows[0]));t.autofit=False
 for i,row in enumerate(rows):
  cs=t.add_row().cells
  for j,(c,txt) in enumerate(zip(cs,row)):
   if widths:c.width=Cm(widths[j])
   c.text=txt;c.vertical_alignment=WD_CELL_VERTICAL_ALIGNMENT.CENTER
   pr=c._tc.get_or_add_tcPr();b=OxmlElement('w:tcBorders')
   for e in ['top','left','bottom','right']:
    el=OxmlElement('w:'+e);el.set(qn('w:val'),'single');el.set(qn('w:sz'),'4');el.set(qn('w:color'),'D9D9D9');b.append(el)
   pr.append(b)
   if i==0:
    sh=OxmlElement('w:shd');sh.set(qn('w:fill'),'EAE9E5');pr.append(sh)
   for par in c.paragraphs:
    par.paragraph_format.space_after=Pt(4);par.paragraph_format.space_before=Pt(3)
    for r in par.runs:r.font.size=Pt(9);r.bold=(i==0)
  tr=t.rows[-1]._tr;pr=tr.get_or_add_trPr();el=OxmlElement('w:cantSplit');pr.append(el)
  if i==0:el=OxmlElement('w:tblHeader');pr.append(el)
 return t
